				if not self.State.PotatoBackup[obj] then
					self.State.PotatoBackup[obj] = {Type="SpecialMesh",TextureId=obj.TextureId};
				end
				obj.TextureId = "";
			end
		elseif (obj:IsA("Decal") or obj:IsA("Texture")) then
			if not self.State.PotatoBackup[obj] then
				self.State.PotatoBackup[obj] = {Type="Decal",[LUAOBFUSACTOR_DECRYPT_STR_0("\101\103\206\250\4\65\116\221\241\25\82\108", "\119\49\21\175\148")]=obj.Transparency};
			end
			obj.Transparency = 1;
		elseif (obj:IsA("ParticleEmitter") or obj:IsA("Smoke") or obj:IsA("Fire") or obj:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\100\165\23\79\38\69\143\230", "\149\55\213\118\61\77\41\234")) or obj:IsA("Light")) then
			if not self.State.PotatoBackup[obj] then
