Hub.IsCoinBagFull = function(self)
	local isFull = false;
	pcall(function()
		local lp = self.Services.Players.LocalPlayer;
		local pgui = lp:FindFirstChild("PlayerGui");
		local mg = pgui and pgui:FindFirstChild("MainGUI");
		if not mg then
			return;
		end
		local coinBags = mg:FindFirstChild("Game") and mg.Game:FindFirstChild("CoinBags");
		if not coinBags then
			return;
		end
		local container = coinBags:FindFirstChild("Container");
		if container then
			for _, bagFrame in ipairs(container:GetChildren()) do
				if (bagFrame:IsA("Frame") and bagFrame.Visible) then
					local icon = bagFrame:FindFirstChild("CurrencyFrame") and bagFrame.CurrencyFrame:FindFirstChild("Icon");
					local coinsLabel = icon and icon:FindFirstChild("Coins");
					local count = tonumber((coinsLabel and coinsLabel.Text) or "0") or 0;
					if (count >= (self.Config.Values.AutoFarmBagLimit or 40)) then
						isFull = true;
						return;
					end
					local fullLabel = bagFrame:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\157\22\226\245", "\161\219\99\142\153\117"));
					if (fullLabel and fullLabel.Visible) then
						isFull = true;
						return;
					end
				end
			end
		end
		local scriptFolder = coinBags:FindFirstChild("CoinBagContainerScript");
		local fullNotif = scriptFolder and scriptFolder:FindFirstChild("FullBagNotification");
		if (fullNotif and fullNotif.Visible) then
			isFull = true;
			return;
		end
	end);
	return isFull;
end;
Hub.GetAvailableCoins = function(self)
