			for _, c in ipairs(coinContainer:GetChildren()) do
				if (c:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\106\185\213\162\104\73\170\210", "\56\40\216\166\199")) and c.Parent and not c:GetAttribute("Collected")) then
					table.insert(list, c);
