		root.AssemblyLinearVelocity = Vector3.new(0, 0, 0);
		root.CFrame = targetPart.CFrame + Vector3.new(0, 3.5, 0);
		if firetouchinterest then
			pcall(function()
				firetouchinterest(root, targetPart, 0);
				firetouchinterest(root, targetPart, 1);
			end);
		end
	end
