Hub.ResolveAnimationId = function(self, assetId)
	local rawId = tostring(assetId);
	local ok, objs = pcall(game.GetObjects, game, "rbxassetid://" .. rawId);
	if (ok and objs and (#objs > 0)) then
		for _, obj in ipairs(objs) do
			if (obj:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\141\26\55\193\182\12\165\27\48", "\120\204\116\94\172\215")) and (obj.AnimationId ~= "")) then
				return obj.AnimationId;
			end
			local found = obj:FindFirstChildWhichIsA(LUAOBFUSACTOR_DECRYPT_STR_0("\34\179\177\5\234\182\121\112\13", "\31\99\221\216\104\139\194\16"), true);
			if (found and (found.AnimationId ~= "")) then
				return found.AnimationId;
			end
		end
	end
	return "rbxassetid://" .. rawId;
end;
